reference_pwsh:
$p = Join-Path $PWD 'config/legacy.ini'; $l = [IO.File]::ReadAllLines($p); $s = ''
$t = [IO.File]::ReadAllText($p); $eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
for ($i = 0; $i -lt $l.Count; $i++) {
  if ($l[$i] -match '^\[(.+)\]$') { $s = $Matches[1] }
  elseif ($s -eq 'server' -and $l[$i].StartsWith('host =')) { $l[$i] = 'host = 127.0.0.1' }
}
[IO.File]::WriteAllText($p, ($l -join $eol) + $eol)
